<?php require '../../includes/header.php';require '../../includes/role_guard.php';requireRole(['admin']);require '../../includes/db.php';$tribes=[];$r=$conn->query("SELECT DISTINCT tribe FROM user_tribes WHERE tribe<>'' UNION SELECT DISTINCT tribe FROM ip_records WHERE tribe<>'' ORDER BY tribe");while($x=$r->fetch_row())$tribes[]=$x[0];$state=$_SESSION['family_import_preview']??null;$errors=['invalid_file'=>'Select a valid XLSX workbook up to 10 MB.','duplicate_file'=>'This exact workbook has already been registered as an import batch.','parse_failed'=>'The workbook headers or contents could not be validated.','preview_expired'=>'The private preview expired. Upload the workbook again.','ownership_required'=>'Select an operational ownership scope.','import_failed'=>'The import transaction failed. No family rows were committed.'];$error=$errors[$_GET['error']??'']??'';?><main class="main-no-right"><div class="page-heading"><div><h4>Controlled Family Import</h4><p>Upload, preview, validate, and explicitly confirm an LCE-format workbook.</p></div><a class="btn btn-light border" href="../families.php">Back to families</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['completed'])):?><div class="alert alert-success">Import batch #<?=(int)$_GET['completed']?> completed. Review the family registry and batch summary.</div><?php endif;?>
<?php if(!$state||!isset($_GET['preview'])):?><section class="card-box"><div class="section-title">1. Select workbook and ownership</div><p class="text-muted">The workbook is stored temporarily outside public web storage. Uploading only creates a preview; it does not change family records.</p><form method="post" action="../../processes/family_import_preview.php" enctype="multipart/form-data"><div class="row g-3"><div class="col-md-7"><label class="form-label">LCE family workbook (.xlsx)</label><input class="form-control" type="file" name="workbook" accept=".xlsx" required></div><div class="col-md-5"><label class="form-label">Operational ownership *</label><select class="form-select" name="owning_tribe" required><option value="">Select approved scope</option><?php foreach($tribes as $tribe):?><option><?=e($tribe)?></option><?php endforeach;?></select></div><div class="col-12"><button class="btn btn-success">Generate Private Preview</button></div></div></form></section>
<?php else:$p=$state['preview'];?><div class="row g-3 mb-3"><?php foreach(['Total rows'=>$p['total'],'Valid'=>$p['valid'],'Warnings'=>$p['warning'],'Invalid'=>$p['invalid'],'Probable duplicates'=>$p['duplicates'],'With spouse'=>$p['with_spouse'],'Without spouse'=>$p['without_spouse']] as $label=>$value):?><div class="col-6 col-lg"><div class="card-box h-100"><small class="text-muted"><?=$label?></small><h3 class="mb-0"><?=(int)$value?></h3></div></div><?php endforeach;?></div><div class="row g-3"><div class="col-lg-5"><section class="card-box h-100"><div class="section-title">Affiliation Distribution</div><?php foreach($p['affiliations'] as $name=>$count):?><div class="d-flex justify-content-between border-bottom py-2"><span><?=e($name)?></span><strong><?=(int)$count?></strong></div><?php endforeach;?></section></div><div class="col-lg-7"><section class="card-box h-100"><div class="section-title">Validation Issues</div><div class="table-responsive" style="max-height:340px"><table class="table table-sm"><thead><tr><th>Source row</th><th>Status</th><th>Issue</th></tr></thead><tbody><?php foreach(array_slice($p['issues'],0,100) as $issue):?><tr><td><?=$issue['row']?></td><td><span class="badge <?=$issue['status']==='invalid'?'bg-danger':'bg-warning text-dark'?>"><?=e($issue['status'])?></span></td><td><?=e(implode('; ',$issue['issues']))?></td></tr><?php endforeach;?><?php if(!$p['issues']):?><tr><td colspan="3">No validation issues.</td></tr><?php endif;?></tbody></table></div></section></div></div><section class="card-box mt-3"><div class="d-flex flex-column flex-md-row justify-content-between gap-3"><div><strong>Ready for explicit confirmation</strong><p class="text-muted mb-0">Valid and warning rows will import; invalid rows will be skipped. Ownership: <?=e($state['ownership'])?>.</p></div><form method="post" action="../../processes/family_import_confirm.php"><input type="hidden" name="preview_token" value="<?=e($state['token'])?>"><button class="btn btn-success" <?=$p['valid']+$p['warning']===0?'disabled':''?>>Confirm Transactional Import</button></form></div></section><?php endif;?></main><?php require '../../includes/footer.php';?>
